<!DOCTYPE html>
<html>
<head>
<title>Simple Desktop</title>
<style>
body {
  background-color: #303030;
  font-family: sans-serif;
}

#desktop {
  width: 80%;
  margin: 20px auto;
  border: 1px solid #555;
  box-shadow: 0 0 10px rgba(0, 0, 0, 0.3);
}

#taskbar {
  width: 80%;
  margin: 0 auto;
  background-color: #444;
  padding: 10px;
  border-bottom: 1px solid #555;
}

#open-files, #open-notepad {
  background-color: #666;
  color: white;
  padding: 5px 10px;
  border-radius: 5px;
  margin-right: 10px;
  cursor: pointer;
}

.win-close {
  content: "×";
  font-size: 20px;
  float: right;
  color: white;
  cursor: pointer;
  padding: 5px;
}

.fs-item {
  margin-bottom: 5px;
  padding: 5px;
  border: 1px solid #777;
  background-color: #444;
  border-radius: 3px;
  cursor: pointer;
}

.fs-item:hover {
  background-color: #555;
}

#files-path {
  margin-bottom: 10px;
  font-weight: bold;
  color: #aaa;
}

#tabs {
  display: flex;
}

.tab {
  background-color: #666;
  color: white;
  padding: 5px 10px;
  border-radius: 3px;
  cursor: pointer;
  margin-right: 5px;
}

.tab:hover {
  background-color: #777;
}

#editor {
  width: 400px;
  height: 300px;
  border: 1px solid #888;
  padding: 10px;
  font-family: monospace;
}
</style>
</head>
<body>

<div id="desktop">
  <div id="taskbar">
    <button id="open-files">Files</button>
    <button id="open-notepad">Notepad</button>
  </div>

  <div id="files-path">/</div>

  <ul id="files-list">
    <li class="fs-item" data-path="/">bin</li>
    <li class="fs-item" data-path="/etc">etc</li>
    <li class="fs-item" data-path="/home">home</li>
    <li class="fs-item" data-path="/usr">usr</li>
    <li class="fs-item" data-path="/var">var</li>
    <li class="fs-item" data-path="/home/user">
      <span class="fs-item" onclick="listFiles('/home/user')">Documents</span>
      <span class="fs-item" onclick="listFiles('/home/user/Documents')">Downloads</span>
      <span class="fs-item" onclick="listFiles('/home/user/Pictures')">Pictures</span>
    </li>
  </ul>

  <div id="files-up"></div>
</div>

<div id="notepad">
  <div id="tabs">
    <button class="tab" data-tab="">New</button>
  </div>
  <div id="editor"></div>
  <div id="new-tab" onclick="createNewTab()">New Tab</div>
</div>


<script>
const filesList = document.getElementById('files-list');
const filesPath = document.getElementById('files-path');
const filesUp = document.getElementById('files-up');

let currentFilesPath = '/';

function listFiles(path) {
  currentFilesPath = path;
  filesPath.textContent = currentFilesPath;
  filesList.innerHTML = '';

  fetch(`/api/files?path=${currentFilesPath}`)
    .then(response => response.json())
    .then(data => {
      data.forEach(item => {
        const listItem = document.createElement('li');
        listItem.className = 'fs-item';
        listItem.setAttribute('data-path', item.path);
        listItem.onclick = () => listFiles(item.path);
        listItem.textContent = item.name;
        filesList.appendChild(listItem);
      });
    })
    .catch(error => console.error("Error fetching files:", error));
}

function openFilesWindow() {
  const filesWindow = document.getElementById('files-window');
  filesWindow.style.display = 'block';
}

function openNotepadWindow() {
  const notepad = document.getElementById('notepad');
  notepad.style.display = 'block';
}


// localStorage for Notepad
if (localStorage.getItem("tabs") === null) {
    localStorage.setItem("tabs", JSON.stringify([]));
}

function createNewTab() {
  const tabs = document.querySelectorAll('.tab');
  const editor = document.getElementById('editor');

  const newTab = document.createElement('button');
  newTab.className = 'tab';
  newTab.setAttribute('data-tab', ''); // Add a unique ID for each tab
  newTab.textContent = 'New Tab';

  tabs[0].disabled = true;
  tabs.forEach(tab => {
    tab.disabled = false;
  });


  const tabsArray = JSON.parse(localStorage.getItem("tabs"));
  tabsArray.push({id: newTab.textContent, content: ""});
  localStorage.setItem("tabs", JSON.stringify(tabsArray));

  newTab.onclick = () => {
    // You'd ideally switch editors here based on tab ID
    editor.innerHTML = ''; // Clear the editor for the new tab
  };

  document.getElementById('tabs').appendChild(newTab);
}


function saveTabContent(tabId) {
   const tabsArray = JSON.parse(localStorage.getItem("tabs"));
    for (let i = 0; i < tabsArray.length; i++) {
        if (tabsArray[i].id === tabId) {
            tabsArray[i].content = editor.innerText;
            break;
        }
    }
    localStorage.setItem("tabs", JSON.stringify(tabsArray));
}

function loadTabContent(tabId) {
    const tabsArray = JSON.parse(localStorage.getItem("tabs"));
    for (let i = 0; i < tabsArray.length; i++) {
        if (tabsArray[i].id === tabId) {
            editor.innerText = tabsArray[i].content;
            break;
        }
    }
}

// Example of how to handle editor clicks for loading content
editor.addEventListener('click', function(event) {
    const target = event.target;
    if (target.classList.contains('tab')) {
      const tabId = target.dataset.tab; // Assuming tabs have a data-tab attribute
      loadTabContent(tabId);
    }
});

</script>

</body>
</html>
